/// Replace `var()`, `env()`, and `attr()` functions in a pre-existing variable value.
pub fn substitute_references_if_needed_and_apply(
    name: &Name,
    namespace: Option<&Namespace>,
    value: &Arc<VariableValue>,
    stylist: &Stylist,
    context: &mut computed::Context,
    attribute_tracker: &mut AttributeTracker,
) {
    let is_var = namespace.is_none();
    let registration = stylist.get_custom_property_registration(name);
    if is_var && !value.has_references() && registration.is_universal() {
        // Trivial path: no references and no need to compute the value, just apply it directly.
        let computed_value = ComputedRegisteredValue::universal(Arc::clone(value));
        context
            .builder
            .substitution_functions
            .insert_var(registration, name, computed_value);
        return;
    }

    let url_data = &value.url_data;
    let mut state = SubstitutionState::default();
    if is_var {
        state.names.push(name);
    }
    let substitution = substitute_internal(
        value,
        Some(PropertyIdRef::from(name)),
        &context.builder.substitution_functions,
        stylist,
        context,
        attribute_tracker,
        &mut state,
        None,
        false,
    );

match namespace {
    None => {
        let value = match substitution.into_value(
            url_data,
            registration,
            context,
            Some(PropertyIdRef::from(name)),
        ) {
            Ok(v) => v,
            Err(()) => {
                handle_invalid_at_computed_value_time(name, registration, context);
                return;
            },
        };
        context
            .builder
            .substitution_functions
            .insert_var(registration, name, value);
    },
    Some(namespace) => {
        let mut value =
            ComputedRegisteredValue::universal(Arc::new(VariableValue::new_resolved(
                substitution.css.into_owned(),
                url_data,
                substitution.first_token_type,
                substitution.last_token_type,
            )));
        value.attr_tainted |= substitution.attr_tainted;
        context
            .builder
            .substitution_functions
            .insert_attr(name, namespace, value);
    },
}

        RegisteredSubstitutionDefault::NotDefaulted
    }
}

fn from_value(v: VariableValue, attr_tainted: bool) -> Self {
    Substitution {
        animation_tainted: v.explicitly_animation_tainted,
        css: v.css.into(),
        first_token_type: v.first_token_type,
        last_token_type: v.last_token_type,
        attr_tainted,
    }
}

fn into_value(
    self,
    url_data: &UrlExtraData,
    registration: &PropertyDescriptors,
    computed_context: &computed::Context,
    property_id: Option<PropertyIdRef>,
) -> Result<ComputedRegisteredValue, ()> {

|attr| {
    let attr = if let AttributeType::Type(_) = &reference.attribute_data.kind {
        // If we're evaluating a container query, we haven't run the cascade
        // and populated substitution_functions.attributes, so we can't do the
        // get_attr() lookup here.
        // TODO: This means chained attr() references will not work reliably in
        // container style queries:
        // https://bugzilla.mozilla.org/show_bug.cgi?id=2028861
        if computed_context.in_container_query {
            attr
        } else {
            substitution_functions
                .get_attr(&reference.name, namespace?)
                .map(|v| v.to_variable_value())?
                .css
        }
    } else {
        attr
    };
    let mut parser = Parser::new(&attr);
    match &reference.attribute_data.kind {
        AttributeType::Unit(unit) => {
            let css = {
                let mut s = String::from(parse_attr_number(&mut parser).ok()?);
                s.push_str(unit.as_ref());
                s
            };
            let serialization = match unit {
                AttrUnit::Number => TokenSerializationType::Number,
                AttrUnit::Percentage => TokenSerializationType::Percentage,
                _ => TokenSerializationType::Dimension,
            };
            let value =
                ComputedValue::new(css, url_data, serialization, serialization);
            Some(Substitution::from_value(
                value, /* attr_tainted */ true,
            ))
        },
        AttributeType::Type(_) => {
            let value = reference
                .attribute_data
                .parse_typed_value(&mut parser, url_data, property_id)
                .ok()?;
            let value = value.to_variable_value();
            Some(Substitution::from_value(
                value, /* attr_tainted */ true,
            ))
        },

let substitution = substitution.filter(|value| {
    !(reference.substitution_kind == SubstitutionFunctionKind::Var
        && value.animation_tainted
        && !suppress_animation_taint_sink
        && matches!(property_id, Some(PropertyIdRef::NonCustom(id)) if !id.is_animatable()))
});
if let Some(s) = substitution {
    return Ok(s);
}

let Some(ref fallback) = reference.fallback else {
    return Err(());
};

do_substitute_chunk(
    css,
    fallback.start.get(),
    reference.end - 1, // Skip the closing parenthesis of the reference value.
    fallback.first_token_type,
    fallback.last_token_type,
    url_data,
    property_id,
    substitution_functions,
    stylist,
    computed_context,
    &fallback.references.refs,
    attribute_tracker,
    seen,
    /* attr_taint */ None,
    suppress_animation_taint_sink,
)

}

let next_var = if next.substitution_kind == SubstitutionFunctionKind::Attr {
    if !next.is_attr_with_type() {
        if let Some(ref fallback) = next.fallback
            && !next
                .attribute_data
                .non_type_primary_is_valid(&next.name, attribute_tracker)
        {
            refs_stack.push(&fallback.references);
        }
        continue;
    }
    let Some(namespace) = next.attribute_data.namespace() else {
        if let Some(ref fallback) = next.fallback {
            refs_stack.push(&fallback.references);
        }
        continue;
    };
    if !context.map().contains_attr(&next.name, namespace)
        && let Ok(val) = get_attr_value_for_cycle_resolution(
            &next.name,
            &next.attribute_data,
            url_data,
            attribute_tracker,
        )
    {
        context.map_mut().insert_attr(&next.name, namespace, val);
    }
    VarType::Attr(next.name.clone(), namespace.clone())
} else {
    VarType::Custom(next.name.clone())
};

visit_link(
    next_var,
    index,

value_non_custom_refs = find_non_custom_references(registration, value, is_root);
registered = !registration.is_universal();
let has_dependency = value
    .references
    .flags
    .intersects(ReferenceFlags::ATTR | ReferenceFlags::VAR)
    || !value_non_custom_refs.is_empty();
// Nothing to resolve.
if !has_dependency {
    debug_assert!(
        !value.references.flags.intersects(ReferenceFlags::ENV),
        "Should've been handled earlier"
    );
    if kind == SubstitutionFunctionKind::Attr || registered {
        // We might still need to compute the value if this is not an universal
        // registration but we thought it had a dependency during the cascade and it
        // turned out not to. Note that if this was already computed we would've
        // bailed out in the as_universal() check.
        let value = value.clone();
        substitute_references_if_needed_and_apply(
            name,
            var.namespace(),
            &value,
            context.stylist,
            context.computed_context,
            attribute_tracker,
        );
    }
    return None;

}

if in_loop {
    return None;
}

// Not in a loop, apply the value.
match var {
    VarType::Custom(ref name) | VarType::Attr(ref name, _) => {
        if let Some(ref v) = value {
            // We know we're not in a loop now, perform substitution.
            // TODO(emilio): Merge with the cycle detection loop instead?
            substitute_references_if_needed_and_apply(
                name,
                var.namespace(),
                v,
                context.stylist,
                context.computed_context,
                attribute_tracker,
            );
        }
    },
    VarType::NonCustom(non_custom) => {
        context.apply_prioritary_property(non_custom.to_prioritary_id(), attribute_tracker);
    },
